114:   cargarPeriodo() {
115:     return new Promise((resolve, reject) => {
116:       this.parametrosService
117:         .get("periodo?query=CodigoAbreviacion:PA&sortby=InicioVigencia,Id&order=desc,desc&limit=0")
118:         .subscribe(
119:           (res: any) => {
120:             const r = <any>res;
121:             if (res !== null && r.Status === "200") {
122:               this.periodo = res.Data.find((p: any) => p.Activo);
123:               window.localStorage.setItem(
124:                 "IdPeriodo",
125:                 String(this.periodo["Id"])
126:               );
127:               resolve(this.periodo);
128:               const periodos = <any[]>res["Data"];
129:               periodos.forEach((element) => {
130:                 this.periodos.push(element);
131:               });
132:             }
133:           },
134:           (error: HttpErrorResponse) => {
135:             reject(error);
136:           }
137:         );
138:     });
139:   }
