164:     }
165:     if (proyecto["NivelFormacionId"]["NivelFormacionPadreId"] !== null) {
166:       if (
167:         proyecto["NivelFormacionId"]["NivelFormacionPadreId"]["Id"] ===
168:         this.selectednivel
169:       ) {
170:         return true;
171:       } else {
172:         return false;
173:       }
174:     } else {
175:       return false;
176:     }
177:   }
